command.mac:
gh auth switch -u shivinate7
(
cd ~/Desktop || { echo "No Desktop folder"; exit 1; }
[ -s dev.p12 ] || { echo "dev.p12 is missing or empty in $(pwd)"; exit 1; }
b64=$(base64 < dev.p12 | tr -d '\n')
[ -n "$b64" ] || { echo "base64 of dev.p12 came out empty"; exit 1; }
gh secret set ASC_DEV_CERT_P12 --repo shivinate7/mailaudit --body "$b64" || { echo "Setting ASC_DEV_CERT_P12 failed"; exit 1; }
printf 'Passphrase of dev.p12: '; read -r -s pw; echo
[ -n "$pw" ] || { echo "Empty passphrase: nothing set"; exit 1; }
gh secret set ASC_DEV_CERT_PASSWORD --repo shivinate7/mailaudit --body "$pw" || { echo "Setting the second secret failed"; exit 1; }
gh secret list --repo shivinate7/mailaudit | grep ASC_DEV_CERT
)

command.powershell:
gh auth switch -u shivinate7
$f = Join-Path $env:USERPROFILE 'Desktop\dev.p12'
if (-not (Test-Path $f) -or (Get-Item $f).Length -eq 0) { Write-Host "dev.p12 is missing or empty: $f"; return }
$b64 = [Convert]::ToBase64String([IO.File]::ReadAllBytes($f))
if (-not $b64) { Write-Host 'base64 of dev.p12 came out empty'; return }
gh secret set ASC_DEV_CERT_P12 --repo shivinate7/mailaudit --body $b64
if ($LASTEXITCODE -ne 0) { Write-Host 'Setting ASC_DEV_CERT_P12 failed'; return }
$sec = Read-Host 'Passphrase of dev.p12' -AsSecureString
$pw = [Runtime.InteropServices.Marshal]::PtrToStringAuto([Runtime.InteropServices.Marshal]::SecureStringToBSTR($sec))
if (-not $pw) { Write-Host 'Empty passphrase: nothing set'; return }
gh secret set ASC_DEV_CERT_PASSWORD --repo shivinate7/mailaudit --body $pw
if ($LASTEXITCODE -ne 0) { Write-Host 'Setting the second secret failed'; return }
gh secret list --repo shivinate7/mailaudit | Select-String ASC_DEV_CERT
